Describe 'install.ps1' {
    BeforeAll {
        # Every case that lets the installer run shadows Invoke-RestMethod with
        # a function that throws. Command resolution prefers functions over
        # cmdlets, so the first network call fails with this sentinel and
        # nothing is downloaded. Cases that need it run in a child process of
        # the same shell, so the Windows PowerShell 5.1 and pwsh CI steps each
        # test their own host; the child's own `exit 7` is the proof that the
        # installer did not terminate the session.
        function Invoke-InstallerChild {
            param([string] $Body)
            $shell = (Get-Process -Id $PID).Path
            $command = "function Invoke-RestMethod { throw 'entire-test: network blocked' }; $Body"
            $output = @(& $shell -NoProfile -NonInteractive -Command $command 2>&1 | ForEach-Object { "$_" })
            [pscustomobject]@{ Output = $output; ExitCode = $LASTEXITCODE }
        }

        function Invoke-InstallerFile {
            param([string[]] $Arguments)
            $shell = (Get-Process -Id $PID).Path
            $command = "function Invoke-RestMethod { throw 'entire-test: network blocked' }; & '$script:installerPath' $Arguments"
            $output = @(& $shell -NoProfile -NonInteractive -File $script:installerPath @Arguments 2>&1 | ForEach-Object { "$_" })
            [pscustomobject]@{ Output = $output; ExitCode = $LASTEXITCODE }
        }
    }

    Context 'documented invocation shapes' {
        It 'runs as a scriptblock with -Help' {
            $installer = [scriptblock]::Create((Get-Content -Raw (Join-Path (Split-Path -Parent $PSScriptRoot) 'install.ps1')))
            $output = @(& $installer -Help 6>&1 | ForEach-Object { "$_" })
            $output[0] | Should -BeLike 'Usage: install.ps1*'
        }

        It 'binds -Channel nightly through the scriptblock form' {
            $installer = [scriptblock]::Create((Get-Content -Raw (Join-Path (Split-Path -Parent $PSScriptRoot) 'install.ps1')))
            $output = @(& $installer -Channel nightly -Help 6>&1 | ForEach-Object { "$_" })
            $output[0] | Should -BeLike 'Usage: install.ps1*'
        }
    }

    Context 'error path when piped to Invoke-Expression' {
        BeforeAll {
            $installerPath = Join-Path (Split-Path -Parent $PSScriptRoot) 'install.ps1'
            $run = Invoke-InstallerChild -Body "try { Get-Content -Raw '$installerPath' | Invoke-Expression } catch { 'CAUGHT:' + `$_.Exception.Message }; 'ALIVE'; exit 7"
        }

        It 'reaches the installer with default parameters' {
            $run.Output | Should -Contain '==> Installing Entire CLI...'
        }

        It 'throws an Error: message instead of printing it' {
            @($run.Output | Where-Object { $_ -like 'CAUGHT:Error: *' }) | Should -HaveCount 1
            @($run.Output | Where-Object { $_ -like 'Error: *' }) | Should -HaveCount 0
        }

        It 'fails at the first network call' -Skip:($env:OS -ne 'Windows_NT') {
            $run.Output | Should -Contain 'CAUGHT:Error: entire-test: network blocked'
        }

        It 'leaves the calling session running' {
            $run.Output | Should -Contain 'ALIVE'
            $run.ExitCode | Should -Be 7
        }
    }

    Context 'error path when run as a scriptblock with parameters' {
        BeforeAll {
            $installerPath = Join-Path (Split-Path -Parent $PSScriptRoot) 'install.ps1'
            $installDir = Join-Path $TestDrive 'bin'
            $run = Invoke-InstallerChild -Body "try { & ([scriptblock]::Create((Get-Content -Raw '$installerPath'))) -InstallDir '$installDir' } catch { 'CAUGHT:' + `$_.Exception.Message }; 'ALIVE'; exit 7"
        }

        It 'reaches the installer with bound parameters' {
            $run.Output | Should -Contain '==> Installing Entire CLI...'
        }

        It 'throws an Error: message instead of printing it' {
            @($run.Output | Where-Object { $_ -like 'CAUGHT:Error: *' }) | Should -HaveCount 1
            @($run.Output | Where-Object { $_ -like 'Error: *' }) | Should -HaveCount 0
        }

        It 'fails at the first network call' -Skip:($env:OS -ne 'Windows_NT') {
            $run.Output | Should -Contain 'CAUGHT:Error: entire-test: network blocked'
        }

        It 'leaves the calling session running' {
            $run.Output | Should -Contain 'ALIVE'
            $run.ExitCode | Should -Be 7
        }
    }

    Context 'error path when run from a file' {
        BeforeAll {
            $shell = (Get-Process -Id $PID).Path
            $installerPath = Join-Path (Split-Path -Parent $PSScriptRoot) 'install.ps1'
            $installDir = Join-Path $TestDrive 'bin'
            # -File, not `& script` inside -Command: the script's `exit 1` ends
            # only the script when it is called from a -Command session.
            $output = @(& $shell -NoProfile -NonInteractive -Command "function Invoke-RestMethod { throw 'entire-test: network blocked' }; & '$shell' -NoProfile -NonInteractive -File '$installerPath' -InstallDir '$installDir'; exit `$LASTEXITCODE" 2>&1 | ForEach-Object { "$_" })
            $exitCode = $LASTEXITCODE
        }

        It 'reaches the installer' {
            $output | Should -Contain '==> Installing Entire CLI...'
        }

        It 'prints one Error: line and no exception formatting' {
            @($output | Where-Object { $_ -like 'Error: *' }) | Should -HaveCount 1
            @($output | Where-Object { $_ -match 'At line:|CategoryInfo|FullyQualifiedErrorId' }) | Should -HaveCount 0
        }

        It 'fails at the first network call' -Skip:($env:OS -ne 'Windows_NT') {
            $output | Should -Contain 'Error: entire-test: network blocked'
        }

        It 'exits 1' {
            $exitCode | Should -Be 1
        }
    }
}

