            param([string[]] $Arguments)
            $shell = (Get-Process -Id $PID).Path
            $command = "function Invoke-RestMethod { throw 'entire-test: network blocked' }; & '$script:installerPath' $Arguments"
            $output = @(& $shell -NoProfile -NonInteractive -File $script:installerPath @Arguments 2>&1 | ForEach-Object { "$_" })
