        @{ PathVariable = 'SCOOP_GLOBAL_DIR'; InvalidLeaf = 'invalid-global-with*asterisk' }
        @{ PathVariable = 'SCOOP_CACHE_DIR'; InvalidLeaf = 'invalid-cache-with*asterisk' }
